package com.wipro.hibernate;import org.hibernate.*;import java.math.*;public class Main{public static void main(String[]a){String id=a.length>0?a[0]:"2";BigDecimal price=new BigDecimal(a.length>1?a[1]:"20");try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Flower f=s.get(Flower.class,id);if(f==null){System.out.println("Error: No Flower found with id "+id);t.rollback();}else{f.setPrice(price);t.commit();System.out.println("Updated: "+f.getFlowerId()+" "+f.getFlowerName()+" "+f.getColor()+" "+f.getPrice());}}HibernateUtil.getSessionFactory().close();}}